-- kmed-archive 06 : 정한문 · 엄한문 2학기 데이터 가져오기 (여러 번 실행해도 됨 : 해당 범위 내용을 지우고 다시 넣음)
do $do$
declare sj uuid; su uuid; r_mid uuid; r_fin uuid; r_um uuid; u uuid;
begin
  -- 과목 (없으면 생성)
  select id into sj from subjects where name='정한문' and grade=1 and semester=2;
  if sj is null then insert into subjects(grade,semester,name,sort,icon,progress_pool) values (1,2,'정한문',0,'📜','hanmun') returning id into sj;
  else update subjects set progress_pool='hanmun' where id=sj; end if;
  select id into su from subjects where name='엄한문' and grade=1 and semester=2;
  if su is null then insert into subjects(grade,semester,name,sort,icon,progress_pool) values (1,2,'엄한문',1,'🖌️','hanmun') returning id into su;
  else update subjects set progress_pool='hanmun' where id=su; end if;
  -- 범위
  select id into r_mid from ranges where subject_id=sj and name='중간';
  if r_mid is null then insert into ranges(subject_id,name,sort) values (sj,'중간',0) returning id into r_mid; end if;
  select id into r_fin from ranges where subject_id=sj and name='기말';
  if r_fin is null then insert into ranges(subject_id,name,sort) values (sj,'기말',1) returning id into r_fin; end if;
  select id into r_um from ranges where subject_id=su and name='2학기';
  if r_um is null then insert into ranges(subject_id,name,sort) values (su,'2학기',0) returning id into r_um; end if;
  -- 탭 (비어 있을 때만)
  if not exists (select 1 from blocks where subject_id=sj) then
    insert into blocks(subject_id,kind,title,sort) values
      (sj,'jung_translate','해석 쓰기',0),(sj,'hanja_r','한자 → 훈음',1),(sj,'hanja_h','훈음 → 한자',2),
      (sj,'hanja_grid','한자 목록',3),(sj,'wordbook','단어장',4),(sj,'summary','써머리',5);
  end if;
  if not exists (select 1 from blocks where subject_id=su) then
    insert into blocks(subject_id,kind,title,sort) values
      (su,'hanja_r','한자 → 훈음',0),(su,'hanja_h','훈음 → 한자',1),(su,'hanja_grid','한자 목록',2),
      (su,'um_order','순서 맞추기',3),(su,'um_answers','문장 모음',4),(su,'wordbook','단어장',5),(su,'summary','써머리',6);
  end if;

  -- 기존 내용 비우기
  delete from hanja_cards where range_id in (r_mid, r_um);
  delete from jung_lines where range_id = r_mid;
  delete from um_sentences where range_id = r_um;
  delete from hanja_units where range_id = r_um;

