  insert into jung_lines(range_id,page,sort,hanja,eum,translation,notes) values
    (r_mid,$v$1$v$,0,$v$大哉醫乎 其來遠矣 粤自混沌旣判 洪荒始分$v$,$v$대재의호 기래원의 월자혼돈기판 홍황시분$v$,$v$크도다! 의학이여! 그 유래가 오래되었구나! 混沌혼돈이 이미 구분된 것으로부터 天地천지가 비로소 나뉘었다.$v$,ARRAY[$v$自: 스스로 자, ~로부터$v$,$v$哉: 감탄, 의문, 반문의 의미를 만든다.$v$,$v$乎: 의문, 반문, 추측, 감탄 등의 의미를 만든다.$v$,$v$粤: 말 내킬 월. 의미는 없으나 문장의 앞에서 말을 시작할 때 사용함.$v$,$v$混沌: 천지개벽 초에 하늘과 땅이 아직 나누어지지 않은 상태로 사물의 구별이 확실하지 않은 상태이다. 여기서는 太極태극을 의미한다.$v$,$v$洪荒: 宇宙우주 또는 天地천지$v$,$v$→ 의학의 유래가 매우 오래되었음을 기술함.$v$]::text[]),
    (r_mid,$v$2$v$,1,$v$陽之輕淸者 以氣而上浮爲天 陰之重濁者 以形而下凝爲地$v$,$v$양지경청자 이기이상부위천 음지중탁자 이형이하응위지$v$,$v$陽양의 가볍고 맑은 것은 氣기로써 위로 떠올라 하늘이 되고 陰음의 무겁고 흐린 것은 形형으로써 아래로 엉겨서 땅이 되었다.$v$,ARRAY[$v$隆然: 우뚝 솟은 모양.$v$,$v$隤然: 움푹 꺼진 모양.$v$]::text[]),
    (r_mid,$v$2$v$,2,$v$天隆然而位乎上 地隤然而位乎下$v$,$v$천륭연이위호상 지퇴연이위호하$v$,$v$天천은 우뚝 솟아서 위에 위치하였고 地지는 움푹 꺼져서 아래에 위치하였다.$v$,ARRAY[$v$→ 천지 형성$v$]::text[]),
    (r_mid,$v$3$v$,3,$v$於是 陽之精者爲日 東升而西墜$v$,$v$어시 양지정자위일 동승이서추$v$,$v$이로부터 陽양의 精髓정수는 해(日)가 되어서 동쪽에서 올라가서 서쪽으로 떨어지며$v$,ARRAY[$v$精: 정할 정. 깨끗하다, 뛰어나다, 정통하다.$v$,$v$兩儀: 陰陽음양$v$,$v$二曜: 日月일월$v$]::text[]),
    (r_mid,$v$3$v$,4,$v$陰之精者爲月 夜見而晝隱$v$,$v$음지정자위월 야현이주은$v$,$v$陰음의 精髓정수는 달(月)이 되어서 밤에 나타났다가 낮에 숨으니$v$,'{}'::text[]),
    (r_mid,$v$3$v$,5,$v$兩儀立矣 二曜行焉$v$,$v$양의립의 이요행언$v$,$v$陰陽음양이 確立확립되고 해와 달(二曜이요)이 운행하였다.$v$,ARRAY[$v$→ 陰陽음양과 日月일월이 세워지고 운행됨을 기술함.$v$]::text[]),
    (r_mid,$v$4$v$,6,$v$於是 玄氣凝空 水始生也$v$,$v$어시 현기응공 수시생야$v$,$v$이로부터 玄氣현기(검은 기운)가 허공에 엉겨서 水수가 비로소 생겼으며$v$,ARRAY[$v$也: 종결형으로 해석 가능-교수님은 내용이 반복되기에 병렬형으로 해석$v$]::text[]),
    (r_mid,$v$4$v$,7,$v$赤氣炫空 火始生也$v$,$v$적기현공 화시생야$v$,$v$赤氣적기(붉은 기운)가 허공에 빛나서 火화가 비로소 생겼으며$v$,'{}'::text[]),
    (r_mid,$v$4$v$,8,$v$蒼氣浮空 木始生也$v$,$v$창기부공 목시생야$v$,$v$蒼氣창기(푸른 기운)이 허공으로 떠올라 木목이 비로소 생겼으며$v$,'{}'::text[]),
    (r_mid,$v$4$v$,9,$v$素氣橫空 金始生也$v$,$v$소기횡공 금시생야$v$,$v$素氣소기(흰 기운)이 허공을 가로질러 金금이 비로소 생겼으며$v$,'{}'::text[]),
    (r_mid,$v$4$v$,10,$v$黅氣際空 土始生也$v$,$v$금기제공 토시생야$v$,$v$黅氣금기(누런 기운)이 허공에 맞닿아 土토가 비로소 생겼으니$v$,'{}'::text[]),
    (r_mid,$v$4$v$,11,$v$五行備 萬物生 三才之道著矣$v$,$v$오행비 만물생 삼재지도저의$v$,$v$五行오행이 갖추어지고 萬物만물이 탄생하여서 三才삼재의 이치가 드러났다.$v$,ARRAY[$v$三才: 天地人천지인$v$,$v$著: 드러났다, 나타났다.$v$,$v$→ 五行오행이 갖추어짐을 기술함.$v$]::text[]),
    (r_mid,$v$5$v$,12,$v$是以 惟人之生 得天地之正氣$v$,$v$시이 유인지생 득천지지정기$v$,$v$이로써 오직 사람의 生생이 天地천지의 正氣정기를 얻어서$v$,'{}'::text[]),
    (r_mid,$v$5$v$,13,$v$頭圓象天 足方象地$v$,$v$두원상천 족방상지$v$,$v$머리는 둥글어서 天천을 본받고 다리는 모가 나서 地지를 본받았으며$v$,ARRAY[$v$象: 코끼리 상. 본받다.$v$,$v$→ 사람이 제일 귀함$v$]::text[]),
    (r_mid,$v$5$v$,14,$v$天有陰陽 人有氣血$v$,$v$천유음양 인유기혈$v$,$v$天천(天地천지)에 陰陽음양이 있음에 사람에게는 氣血기혈이 있으며$v$,ARRAY[$v$天: =천지자연$v$]::text[]),
    (r_mid,$v$5$v$,15,$v$天有五行 人有五臟$v$,$v$천유오행 인유오장$v$,$v$天천(天地천지)에 五行오행이 있음에 사람에게는 五臟오장이 있다.$v$,ARRAY[$v$→ 天人相應 천인상응의 관점에서 인간과 천지(자연, 우주)의 관계를 기술함.$v$]::text[]),
    (r_mid,$v$6$v$,16,$v$盖葛天氏之民$v$,$v$개갈천씨지민$v$,$v$대개 葛天氏갈천씨 시대의 백성들은$v$,ARRAY[$v$盖: 蓋와 같음. '대개', '아마도'$v$,$v$葛天氏: 상고시대 제왕으로서 아주 이상적으로 세상을 잘 다스려서 천하가 태평했다고 함.$v$]::text[]),
    (r_mid,$v$6$v$,17,$v$巢居穴處$v$,$v$소거혈처$v$,$v$움막과 동굴에서 거처하고$v$,ARRAY[$v$巢居穴處: 巢소는 새둥지처럼 생긴 움막이고, 穴혈은 동굴집이다.$v$]::text[]),
    (r_mid,$v$6$v$,18,$v$茹毛飮血$v$,$v$여모음혈$v$,$v$털을 먹고 피를 마셨으며$v$,ARRAY[$v$茹毛飮血: '털을 먹고 피를 마신다'는 뜻. 자연에 순응하는 생활을 의미함.$v$]::text[]),
    (r_mid,$v$6$v$,19,$v$動作以避其寒$v$,$v$동작이피기한$v$,$v$움직여서 이로써 그 추위를 피하였고$v$,'{}'::text[]),
    (r_mid,$v$6$v$,20,$v$陰居以避其暑$v$,$v$음거이피기서$v$,$v$그늘에 거처해서 이로써 그 더위를 피하였으니$v$,'{}'::text[]),
    (r_mid,$v$6$v$,21,$v$大朴未開$v$,$v$대박미개$v$,$v$매우 소박하고 문명이 열리지 않았으니$v$,ARRAY[$v$朴: 후박나무 박. 순박하다, 꾸밈이 없다.$v$,$v$大朴: 자연 그대로의 삶, 자연에 순응하는 삶$v$]::text[]),
    (r_mid,$v$6$v$,22,$v$何病之有$v$,$v$하병지유$v$,$v$어찌 병이 있으리오!$v$,ARRAY[$v$→ 자연에 순응하는 삶을 살기에 병이 발생하지 않음.$v$]::text[]),
    (r_mid,$v$7$v$,23,$v$迨夫伏羲氏$v$,$v$태부복희씨$v$,$v$저 伏羲氏복희씨에 이르러서는$v$,ARRAY[$v$迨: 미칠 태. 공간적 거리나 수준 따위가 일정한 선에 닿다. 또는 어떤 장소나 시간에 닿다.$v$,$v$夫: 대명사로서 사물이나 사람을 가리키고, 3인칭을 나타낸다.$v$,$v$伏羲氏: 古代고대의 제왕. 三皇五帝삼황오제의 首位수위를 차지하며, 八卦팔괘를 처음 만들고 그물을 발명하여 고기잡이의 방법을 가르쳤다함.$v$,$v$夫: 가로사로 쓰여 '무릇'이라고 해석할 수 있기도 함. but 여기선 3인칭 '저'로 해석$v$]::text[]),
    (r_mid,$v$7$v$,24,$v$占天望氣而畵卦$v$,$v$점천망기이획괘$v$,$v$天文천문을 관측하고 氣象기상을 살펴서 八卦팔괘를 만들어서$v$,ARRAY[$v$占天望氣: 구름이나 大氣대기의 현상을 살펴보고 날씨를 예측하는 일.$v$,$v$占: 예측하다.$v$,$v$天: 천문$v$,$v$望: 보다.$v$,$v$氣: 기상$v$,$v$畵: 그림 화, 그리다 획. 여기선 '그리다 획'으로 해석$v$]::text[]),
    (r_mid,$v$7$v$,25,$v$後世有天元玉冊 目爲伏羲之書者$v$,$v$후세유천원옥책 목위복희지서자$v$,$v$後世후세에 天元玉冊천원옥책은 伏羲복희가 지은 책이라고 指目지목한 사람이 있었으니$v$,ARRAY[$v$天元玉冊: 당나라 王氷왕빙이 지은 운기학 전문서.$v$,$v$천문을 관측해서 천문에 으뜸되는 내용을 옥으로 된 책에 새겼다는 의미로 매우 중요한 책임을 보여줌.$v$,$v$目: 지칭하다, 일컫다. 指目지목$v$]::text[]),
    (r_mid,$v$7$v$,26,$v$乃鬼臾區十世口誦而傳之也$v$,$v$내귀유구십세구송이전지야$v$,$v$곧 鬼臾區귀유구가 十世십세동안 입으로 외워서 傳전한 것이다.$v$,ARRAY[$v$鬼臾區: 鬼容區귀용구, 大鴻대홍이라고도 함. 黃帝황제의 신하 중의 하나. 사람이름$v$,$v$1秒초, 1分분-60秒초, 1時시-60分분, 日일-24時시, 月월-30日일, 年년-12月월, 世세-30年년, 運운-12世세$v$,$v$十世: 300년, 오랜시간$v$]::text[]),
    (r_mid,$v$8$v$,27,$v$神農氏 嘗百草$v$,$v$신농씨 상백초$v$,$v$神農氏신농씨가 온갖 약초를 맛보아$v$,ARRAY[$v$神農氏: 炎帝神農氏염제신농씨. 농사짓는 법을 알려주었고, 百草백초를 직접 맛보아 해독을 하였으며, 한의학의 창시자.$v$,$v$농사와 관련된 신화 속 인물로 본초학을 만든 인물$v$,$v$百: 온갖$v$]::text[]),
    (r_mid,$v$8$v$,28,$v$一日而七十毒$v$,$v$일일이칠십독$v$,$v$하루에 70가지 毒독을 맛보았으니$v$,ARRAY[$v$一日: 하루$v$,$v$毒: 독과 약은 차이가 없음. 적당히 쓰면 약이고, 잘못 쓰면 독임.$v$]::text[]),
    (r_mid,$v$8$v$,29,$v$厥後本草興焉$v$,$v$궐후본초흥언$v$,$v$그 후에 本草본초가 일어났다.$v$,'{}'::text[]),
    (r_mid,$v$9$v$,30,$v$黃帝 垂衣裳而天下治$v$,$v$황제 수의상이천하치$v$,$v$黃帝황제께서 衣裳의상을 드리우고 天下천하를 다스렸으며$v$,ARRAY[$v$黃帝: 중국에서 중국 문명의 始祖시조로 섬기는 전설상의 임금. <史記사기>에 의하면 少典소전의 아들로 이름은 軒轅헌원이며, 蚩尤치우를 물리치고 神農신농에 이어 제왕이 되었다. 의복, 수레를 비롯한 수많은 발명품과 문자, 60갑자, 한의학 등의 학문과 기예를 창시함. 道敎도교의 시조로도 추앙됨.$v$,$v$垂衣裳: 衣의는 윗옷, 裳상은 치마를 뜻하는데, 垂衣裳수의상은 임금의 德化덕화가 온 세상에 두루 미침을 표현함. 衣: 상의, 裳: 하의$v$]::text[]),
    (r_mid,$v$9$v$,31,$v$與岐伯天師 更相問難$v$,$v$여기백천사 갱상문난$v$,$v$天師천사와 함께 번갈아 서로 문제점을 물어서$v$,ARRAY[$v$岐伯天師: 전설에 나오는 上古상고의 의가로서, 岐天師기천사라고도 한다. 黃帝황제와 함께 醫藥의약을 창시한 것으로 나오는데, 黃帝內經황제내경은 황제와 기백이 토론하는 형식으로 구성되어 있다. 황제와 군신관계이며 사제관계이다.$v$,$v$更: 고칠 경. 번갈아, 교대로.$v$]::text[]),
    (r_mid,$v$9$v$,32,$v$上推天文$v$,$v$상추천문$v$,$v$위로는 天文천문을 헤아리고$v$,ARRAY[$v$推: 헤아리다. 추측하다.$v$,$v$天文: 天體천체에서 일어나는 온갖 현상.$v$]::text[]),
    (r_mid,$v$9$v$,33,$v$下窮地理$v$,$v$하궁지리$v$,$v$아래로는 地理지리를 속속들이 깊이 연구하였으며$v$,ARRAY[$v$窮: 궁구하다. 파고들어 깊이 연구하다.$v$,$v$地理: 땅의 형편.$v$]::text[]),
    (r_mid,$v$9$v$,34,$v$中極民瘼$v$,$v$중극민막$v$,$v$가운데로는 백성들의 病병을 지극히 하였으니$v$,ARRAY[$v$極: 극진하다, 지극하다.$v$]::text[]),
    (r_mid,$v$9$v$,35,$v$內經自此而作矣$v$,$v$내경자차이작의$v$,$v$內經내경이 이로부터 지어졌다.$v$,ARRAY[$v$內經: 황제내경$v$,$v$此: 황제와 기백이 천지인에 대해 문답하는 과정.$v$]::text[]),
    (r_mid,$v$10$v$,36,$v$此經旣作 民之有疾$v$,$v$차경기작 민지유질$v$,$v$이 黃帝內經황제내경이 (이미) 著作저작됨에 백성들의 疾病질병이 있음을$v$,ARRAY[$v$經: 황제내경$v$]::text[]),
    (r_mid,$v$10$v$,37,$v$必假砭針以治其外$v$,$v$필가폄침이치기외$v$,$v$반드시 砭針폄침을 빌려서 이로써 그 밖을 치료하고$v$,ARRAY[$v$假: 거짓 가. 빌리다.$v$,$v$砭針: 砭石폄석, 石針석침, 鍼石침석. 쐐기 모양의 돌을 가리키는데, 의료도구의 일종. 신석기 시대에서 기원하였으며, 환부를 砭刺폄자함으로써 각종 동통을 치료하고 排膿배농, 瀉血사혈하는데 사용$v$]::text[]),
    (r_mid,$v$10$v$,38,$v$湯液以療其內$v$,$v$탕액이료기내$v$,$v$湯液탕액으로써 그 내부를 치료하였다.$v$,ARRAY[$v$湯液: 湯劑탕제. 약물을 물에 달인 후 찌꺼기를 버리고 汁즙만 취하여 내복하는 것. 흡수가 빨라 약효가 빨리 나타나므로 新病신병이나 急病급병에 사용함.$v$,$v$탕: 약을 달여서 나온 추출물, 액: 짜서 나온 즙$v$]::text[]),
    (r_mid,$v$11$v$,39,$v$厥後大朴散而風化開$v$,$v$궐후대박산이풍화개$v$,$v$그 후에 크게 소박함이 흩어지고 風習풍습을 敎化교화함이 열리고$v$,ARRAY[$v$朴: 후박나무 박. 소박하다, 순박하다.$v$]::text[]),
    (r_mid,$v$11$v$,40,$v$民務繁而慾心縱$v$,$v$민무번이욕심종$v$,$v$백성들이 번잡한 것에 힘쓰고 慾心욕심을 멋대로 하여서$v$,ARRAY[$v$縱: 늘어질 종, 많을 총. 방종하다, 솟구치다.$v$,$v$繁: 번성할 번. 번거롭다, 복잡하다.$v$,$v$務繁: 소박하지 않게 되고 문명 발달로 인해 이것저것을 많이 하다보니 번잡한 것에 관심이 생김.$v$]::text[]),
    (r_mid,$v$11$v$,41,$v$災沴多端$v$,$v$재려다단$v$,$v$災沴재려가 많았으니$v$,ARRAY[$v$端: 끝 단. 바를 단.$v$,$v$災沴: 재앙.$v$,$v$沴: 해칠 려.$v$,$v$多端: 일이 흐트러져 가닥이 많음. 사건이 많음. 용건이 많음.$v$,$v$→ 문명발생의 단점: 문명이라는 편리함을 자신의 건강을 증진시키고 유지하는데 사용하지 않고 해치는데 사용함.$v$]::text[]),
    (r_mid,$v$11$v$,42,$v$非大毒小毒常毒$v$,$v$비대독소독상독$v$,$v$大毒대독과 小毒소독과 常毒상독의 藥약이 아니면$v$,ARRAY[$v$大毒小毒常毒: 강력한 수단.$v$]::text[]),
    (r_mid,$v$11$v$,43,$v$無毒之藥 弗能蠲矣$v$,$v$무독지약 불능견의$v$,$v$無毒무독의 藥약으로는 (질병을) 덜어낼 수 없었다.$v$,ARRAY[$v$蠲: 덜 견. 밝을 견.$v$,$v$無毒: 평범한 약$v$,$v$→ 사람들의 욕심으로 인해 병이 많이 발생함. 이를 제거하는데 있어서 일상적인 치료방법인 무독, 폄석, 탕액이 효과가 없음. 강력한 수단인 대독, 소독, 상독으로만 치료가 가능함.$v$]::text[]),
    (r_mid,$v$12$v$,44,$v$醫之大原 素問一書而已矣$v$,$v$의지대원 소문일서이이의$v$,$v$의학의 큰 근원은 素問一書소문일서일 뿐이니$v$,ARRAY[$v$而已矣: 語氣訶어기사가 연용된 것으로서, '而已이이'는 한정을 나타내며, '矣의'는 語氣어기를 강화시킴. '~일 뿐이다.'로 해석.$v$]::text[]),
