    (r_mid,$v$21$v$,85,$v$其活人也固多$v$,$v$기활인야고다$v$,$v$그 사람을 살린 것도 진실로 많지만$v$,ARRAY[$v$固: 굳을 고. 진실로.$v$]::text[]),
    (r_mid,$v$21$v$,86,$v$其死人也不寡矣$v$,$v$기사인야불과의$v$,$v$그 사람을 죽게 한 것도 적지 않았다.$v$,ARRAY[$v$寡: 적을 과.$v$,$v$→ 朱奉議주봉의가 陰陽음양을 寒熱한열로 잘못 해석하여, 작은 차이가 큰 오류를 낳았음을 기술함.$v$]::text[]),
    (r_mid,$v$22$v$,87,$v$幸而守眞劉子要旨論 原病式二書旣作$v$,$v$행이수진유자요지론 원병식이서기작$v$,$v$다행히 劉守眞유수진의 要旨論요지론과 原病式원병식의 두 책이 이미 만들어진 즉$v$,ARRAY[$v$守眞劉子: 劉完素유완소. 守眞수진은 字자이며 河間하간 사람이라 劉河間유하간이라고도 함.$v$,$v$要旨論, 原病式: 書名서명.$v$]::text[]),
    (r_mid,$v$22$v$,88,$v$則內經之理 昭如日月之明$v$,$v$즉내경지리 소여일월지명$v$,$v$內經내경의 이치가 해와 달처럼 밝아졌으며$v$,ARRAY[$v$昭: 밝을 소.$v$]::text[]),
    (r_mid,$v$22$v$,89,$v$直格書 宣明論二書旣作$v$,$v$직격서 선명론이서기작$v$,$v$直格書직격서와 宣明論선명론 두 책이 이미 만들어진 즉$v$,ARRAY[$v$直格書, 宣明論: 書名서명$v$]::text[]),
    (r_mid,$v$22$v$,90,$v$則長沙之法 約如樞機之要$v$,$v$즉장사지법 약여추기지요$v$,$v$張仲景장중경의 법도가 樞機추기의 요점과 같이 要約요약되었으니$v$,ARRAY[$v$約: 맺을 약. 줄이다, 묶다.$v$,$v$樞機: 중추가 되는 기관. 몹시 중요한 사물의 부분.$v$]::text[]),
    (r_mid,$v$22$v$,91,$v$如改桂枝麻黃各半湯爲雙解散$v$,$v$여개계지마황각반탕위쌍해산$v$,$v$桂枝麻黃各半湯계지마황각반탕을 雙解散쌍해산으로 고친 것과$v$,ARRAY[$v$桂枝麻黃各半湯, 雙解散: 처방명$v$]::text[]),
    (r_mid,$v$22$v$,92,$v$變十棗湯爲三花神佑丸$v$,$v$변십조탕위삼화신우환$v$,$v$十棗湯십조탕을 변형해서 三花神佑丸삼화신우환으로 만든 것은$v$,ARRAY[$v$十棗湯, 三花神佑丸: 처방명$v$]::text[]),
    (r_mid,$v$22$v$,93,$v$其有功于聖門也不淺矣$v$,$v$기유공우성문야불천의$v$,$v$그 공로가 聖賢성현의 門戶문호에 있으니 얕지 않다.$v$,ARRAY[$v$于: 어조사 우. ~에.$v$,$v$→ 劉守眞유수진(劉河間)이 內經내경의 이치와 張仲景장중경의 법을 밝히고 요약한 공로를 기술함.$v$]::text[]),
    (r_mid,$v$23$v$,94,$v$同時有張子和者出$v$,$v$동시유장자화자출$v$,$v$같은 時代시대에 張子和장자화란 자가 나와서$v$,'{}'::text[]),
    (r_mid,$v$23$v$,95,$v$明內經之大道 續河間之正源$v$,$v$명내경지대도 속하간지정원$v$,$v$內經내경의 大道대도를 밝히고 河間하간의 올바른 근원을 계승하여$v$,ARRAY[$v$續: 이을 속.$v$,$v$河間: 劉守眞유수진(劉河間)$v$]::text[]),
    (r_mid,$v$23$v$,96,$v$與麻知幾講學而作儒門事親之書$v$,$v$여마지기강학이작유문사친지서$v$,$v$麻知幾마지기와 함께 講學강학하여 儒門事親유문사친이란 책을 만들었다.$v$,ARRAY[$v$麻知幾: 人名인명$v$,$v$講學: 학문을 닦고 연구함.$v$,$v$儒門事親: 書名서명$v$]::text[]),
    (r_mid,$v$24$v$,97,$v$乃曰吐中有汗 瀉中有補$v$,$v$내왈토중유한 사중유보$v$,$v$이에 말하기를 "吐토하는 가운데 發汗발한을 하고, 瀉사하는 가운데 補보함이 있으니$v$,ARRAY[$v$曰: 가로 왈. 말하기를.$v$]::text[]),
    (r_mid,$v$24$v$,98,$v$聖人止有三法 無第四法$v$,$v$성인지유삼법 무제사법$v$,$v$聖人성인은 단지 汗한·吐토·下하의 三法삼법만 있을 뿐 네 번째 방법은 없다."고 하였으니$v$,ARRAY[$v$止: 그칠 지. 다만, 단지.$v$,$v$三法: 汗吐下한토하$v$]::text[]),
    (r_mid,$v$24$v$,99,$v$乃不易之確論 至精之格言$v$,$v$내불역지확론 지정지격언$v$,$v$곧 바뀌지 않는 명확한 이론이며 지극히 정밀한 格言격언이니$v$,ARRAY[$v$易: 바꿀 역.$v$]::text[]);
  insert into jung_lines(range_id,page,sort,hanja,eum,translation,notes) values
    (r_mid,$v$24$v$,100,$v$於是有劉張之派矣$v$,$v$어시유유장지파의$v$,$v$이로부터 劉張유장의 學派학파가 있게 되었다.$v$,ARRAY[$v$劉張: 劉河間유하간과 張子和장자화$v$,$v$→ 張子和장자화가 河間하간을 계승하여 汗吐下한토하 三法삼법을 주장하고, 劉張學派유장학파가 형성되었음을 기술함.$v$]::text[]),
    (r_mid,$v$25$v$,101,$v$若東垣老人 明素問之理 宗仲景之法$v$,$v$약동원노인 명소문지리 종중경지법$v$,$v$또한 東垣老人동원노인은 素問소문의 이치를 밝히고 仲景중경의 방법을 근본으로 해서$v$,ARRAY[$v$東垣老人: 李杲이고. 東垣동원은 號호.$v$]::text[]),
    (r_mid,$v$25$v$,102,$v$作濟拔萃十書以傳于世$v$,$v$작제발췌십서이전우세$v$,$v$뽑아 모아 東垣十書동원십서를 만들어 세상에 전하였고$v$,ARRAY[$v$拔萃: 책이나 글에서 필요하거나 중요한 부분을 가려 뽑아냄.$v$]::text[]),
    (r_mid,$v$25$v$,103,$v$明脈取權衡規矩$v$,$v$명맥취권형규구$v$,$v$脈맥을 밝힘에 있어서는 權衡規矩권형규구를 취하였으며$v$,ARRAY[$v$權衡: 저울추와 저울대$v$,$v$規矩: 지름이나 선의 거리를 재는 도구$v$]::text[]),
    (r_mid,$v$25$v$,104,$v$用藥體升降浮沈$v$,$v$용약체승강부침$v$,$v$藥약을 사용함에는 升降浮沈승강부침을 본받았으니$v$,ARRAY[$v$體: 몸 체. 본받다.$v$]::text[]),
    (r_mid,$v$25$v$,105,$v$是以有王道霸道譬焉$v$,$v$시이유왕도패도비언$v$,$v$이러므로 王道왕도와 霸道패도의 비유가 있게 되었다.$v$,ARRAY[$v$王道: 임금이 어진 덕으로 백성을 다스리는 도리$v$,$v$霸道: 인의를 무시하고 무력이나 권모술수로 나라를 다스림.$v$,$v$譬: 비유할 비.$v$,$v$→ 東垣老人동원노인(李杲)이 素問소문과 仲景중경을 근본으로 東垣十書동원십서를 짓고, 脈맥과 用藥용약의 원칙을 세웠음을 기술함.$v$]::text[]),
    (r_mid,$v$26$v$,106,$v$至于丹溪朱氏$v$,$v$지우단계주씨$v$,$v$朱丹溪주단계에 이르러서는$v$,ARRAY[$v$至于: ~에 이르러서는$v$,$v$丹溪朱氏: 朱震亨주진형. 丹溪단계는 號호.$v$]::text[]),
    (r_mid,$v$26$v$,107,$v$傷寒內傷雜病 無不精研$v$,$v$상한내상잡병 무불정연$v$,$v$傷寒상한, 內傷내상, 雜病잡병을 정밀하게 연구하지 않음이 없었으며$v$,ARRAY[$v$精研: 정밀하고 세밀하게 연구함.$v$,$v$無不: ~하지 않음이 없다. (이중부정 → 강한 긍정)$v$]::text[]),
    (r_mid,$v$26$v$,108,$v$痰火奧義 猶其獨得$v$,$v$담화오의 유기독득$v$,$v$痰火담화에 대한 깊은 뜻은 오히려 그가 홀로 터득한 것이었으니$v$,ARRAY[$v$奧義: 매우 깊은 뜻.$v$,$v$猶: 오히려 유.$v$]::text[]),
    (r_mid,$v$26$v$,109,$v$宋太史濂 謂其集醫家之大成$v$,$v$송태사렴 위기집의가지대성$v$,$v$宋송나라의 太史태사였던 濂렴이 그를 '그는 醫家의가를 集大成집대성하였다.'고 말하였으니$v$,ARRAY[$v$宋濂: 人名인명. 明初명초의 문신으로 太史태사를 지냄.$v$,$v$集大成: 여럿을 모아 하나로 크게 완성함.$v$]::text[]),
    (r_mid,$v$26$v$,110,$v$誠哉 是言也$v$,$v$성재 시언야$v$,$v$진실로 그렇구나! 이 말이여!$v$,ARRAY[$v$哉: 감탄을 나타냄.$v$,$v$誠哉是言也: 도치 구문. 是言也誠哉 (이 말이 참되도다)$v$,$v$→ 朱丹溪주단계가 傷寒상한·內傷내상·雜病잡병을 정밀히 연구하고 痰火담화의 이치를 독자적으로 터득하여 醫家의가를 집대성하였음을 기술함.$v$]::text[]);
