    ((select id from hanja_units where range_id=r_um and code=$v$handokgipae$v$),38,$v$吾力足以擧百鈞, 而不足以擧一羽,$v$,ARRAY[$v$吾$v$,$v$力$v$,$v$足以$v$,$v$擧$v$,$v$百鈞$v$,$v$而$v$,$v$不$v$,$v$足以$v$,$v$擧$v$,$v$一羽$v$]::text[],ARRAY[1,2,5,4,3,6,10,9,8,7]::int[],$v$내 힘은 백 균(3천근)을 들 수 있지만, 하나의 깃털을 들 수 없고,$v$,$v$$v$),
